const byte trigPin = 9;
const byte echoPin = 10;

void setup() {
  pinMode(trigPin, OUTPUT);
  pinMode(echoPin, INPUT);
  Serial.begin(9600);
}

void loop() {
  digitalWrite(trigPin, LOW);
  delayMicroseconds(2);
  digitalWrite(trigPin, HIGH);
  delayMicroseconds(10);
  digitalWrite(trigPin, LOW);
  const unsigned long us = pulseIn(echoPin, HIGH, 30000UL);
  if (us == 0) Serial.println("Echo yoxdur");
  else Serial.println(us / 58.0); // təxmini santimetr
  delay(100);
}
